        cu_thread_join(pool->workers[i].thread);
    if (pool->changed != NULL)
        cu_cond_destroy(pool->changed);
    if (pool->mutex != NULL)
        cu_mutex_destroy(pool->mutex);
    cu_arena_release(&pool->arena);
}

static int pool_start(Pool *pool, int count)
{
    int i;
    cu_arena_init(&pool->arena);
    pool->mutex = NULL;
    pool->changed = NULL;
    pool->count = count;
    pool->started = 0;
    pool->ready = 0;
    pool->stop = 0;
    pool->pending = 0;
    for (i = 0; i < 32; ++i) {
        pool->slots[i] = NULL;
        pool->workers[i].pool = pool;
        pool->workers[i].thread = NULL;
    }
    if (!cu_mutex_init(&pool->mutex, &pool->arena) ||
        !cu_cond_init(&pool->changed, &pool->arena))
        return 0;
